<?php get_header(); ?><section class="nv-content"><div class="nv-wrap"><h1><?php echo esc_html(is_home()?get_the_title(get_option('page_for_posts')):wp_get_document_title()); ?></h1><div class="nv-listing"><?php if(have_posts()):while(have_posts()):the_post(); ?><article class="nv-card"><div class="nv-meta"><?php echo esc_html(get_the_date()); ?></div><h2 style="font-size:24px"><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?></article><?php endwhile;else:?><p><?php esc_html_e('Nothing found.','nvconsult'); ?></p><?php endif; ?></div><?php the_posts_pagination(); ?></div></section><?php get_footer(); ?>
